output:
server {
    listen 80;
    server_name shop.example.com;
    return 301 https://$host$request_uri;
}

server {
    listen 80;
    server_name example.net;
    return 301 https://www.example.net$request_uri;
}

server {
    listen 80;
    server_name www.blog.example;
    return 301 https://blog.example$request_uri;
}

server {
    listen 80;
    server_name shop-v2.example.com;
    return 302 https://shop-v2.example.com/maintenance.html;
}

location = /products/old-widget {
    return 410;
}

location ~ ^/blog/(\d{4})/(\d{2})/(.+)$ {
    return 301 /posts/$3;
}

location = /pricing.html {
    return 301 /plans$is_args$args;
}

location /v1/ {
    rewrite ^/v1/(.*)$ /stable/$1 last;
}
location /stable/ {
    root /var/www/api-docs;
    try_files $uri =404;
}

location / {
    root /var/www/dir-site;
    if (-d $request_filename) {
        rewrite ^(.*[^/])$ $uri/ permanent;
    }
    try_files $uri $uri/ =404;
}

location ~ ^/(index|home)\.html$ {
    return 301 /;
}

location ~ ^/article/([a-z0-9-]+)\.html$ {
    return 301 /article/$1;
}

location /forum {
    return 301 https://community.example.org$request_uri;
}

location /legacy/ {
    rewrite ^/legacy/(.*)$ /v2/$1 break;
    proxy_pass http://127.0.0.1:8080;
    proxy_set_header Host $host;
}

server {
    listen 80;
    server_name legacy.example.org;
    root /var/www/site;
    set $maintenance 0;
    if (-f /var/www/site/maintenance.html) {
        set $maintenance 1;
    }
    if ($maintenance = 1) {
        return 503;
    }
    error_page 503 @maintenance;
    location @maintenance {
        rewrite ^(.*)$ /maintenance.html break;
    }
    location / {
        try_files $uri $uri/ =404;
    }
}

location = / {
    return 301 /en/;
}

server {
    listen 80;
    server_name www.canonical.example;
    root /var/www/canonical;
    if ($uri ~ "^(.+)/$") {
        return 301 $scheme://$host$1;
    }
}

server {
    listen 80;
    server_name www.modern.example;
    root /var/www/modern;
    if ($http_user_agent ~* "MSIE [1-9]\.") {
        return 301 http://legacy.example.com$request_uri;
    }
}

location ~* ^/docs/.+\.pdf$ {
    return 301 https://docs.example.io$request_uri;
}

location /portal/ {
    rewrite ^/portal/([a-z0-9-]+)$ /portal/index.php?page=$1 last;
}
location ~ \.php$ {
    root /var/www/portal;
    fastcgi_pass 127.0.0.1:9000;
    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
    include fastcgi_params;
}

map $uri $moved_page {
    default 0;
    /about-us /company;
    /contact-us /contact;
    /pricing /plans;
}
server {
    listen 80;
    server_name www.marketing.example;
    root /var/www/marketing;
    if ($moved_page) {
        return 301 $scheme://$host$moved_page;
    }
}
